the stainless steel air gap enhances cleanliness and hygiene. Designed as a true low-energy dump and fill dish machine, it conserves resources while delivering reliable cleaning performance.<\\/p>\",\"warranty_information\":\"<p>No Warranty<\\/p>\",\"images\":[null,\"https:\\/\\/testhssite.com\\/storage\\/products\\/024-3090.0145_94d9e5e7-36fb-4e66-8460-5d98273a45df.webp\"],\"product_type\":\"physical\",\"sale_type\":\"0\",\"sku\":\"024-3090.0145\",\"price\":\"6039.93\",\"sale_price\":null,\"start_date\":null,\"end_date\":null,\"unit_of_measurement_id\":\"1\",\"cost_per_item\":\"4755.85\",\"margin\":\"21.26%\",\"product_id\":\"1946\",\"barcode\":null,\"with_storehouse_management\":\"0\",\"quantity\":null,\"allow_checkout_when_out_of_stock\":\"0\",\"stock_status\":\"in_stock\",\"discount\":[{\"discount_id\":\"447\",\"product_quantity\":\"4\",\"discount\":\"5\",\"price_after_discount\":\"5737.93\",\"margin\":\"17.12\",\"discount_from_date\":\"2024-12-16T12:16\",\"discount_to_date\":\"2024-12-20T12:16\"},{\"discount_id\":\"448\",\"product_quantity\":\"8\",\"discount\":\"10\",\"price_after_discount\":\"5435.94\",\"margin\":\"12.51\",\"discount_from_date\":\"2024-12-16T12:16\",\"discount_to_date\":\"2024-12-20T12:16\"}],\"weight_unit_id\":\"1\",\"weight\":\"300\",\"length_unit_id\":\"1\",\"length\":\"0\",\"depth\":\"28\",\"height\":\"74\",\"width\":\"29\",\"shipping_length_id\":\"1\",\"shipping_length\":\"0\",\"shipping_depth\":\"0\",\"shipping_height\":\"0\",\"shipping_width\":\"0\",\"is_added_attributes\":\"0\",\"has_product_options\":\"1\",\"deleted_videos\":null,\"shipping_weight\":null,\"shipping_weight_option\":\"Kg\",\"titles\":{\"4\":null,\"5\":null},\"variant_color_title\":\"Color\",\"variant_color_value\":null,\"variant_color_products\":null,\"variant_1_title\":null,\"variant_1_value\":null,\"variant_1_products\":null,\"variant_2_title\":null,\"variant_2_value\":null,\"variant_2_products\":null,\"variant_3_title\":null,\"variant_3_value\":null,\"variant_3_produ