INSERT INTO `audit_histories` (`id`, `user_id`, `module`, `request`, `action`, `user_agent`, `ip_address`, `reference_user`, `reference_id`, `reference_name`, `type`, `created_at`, `updated_at`) VALUES
(8238, 1, 'product', '{\"name\":\"Arctic Air ARCB72 72\\\" Four Drawer Refrigerated Chef Base\",\"model\":\"Botble\\\\Ecommerce\\\\Models\\\\Product\",\"slug\":\"arctic-air-arcb72-72-four-drawer-refrigerated-chef-base\",\"slug_id\":\"2099\",\"is_slug_editable\":\"1\",\"description\":\"<p>The Arctic Air ARCB72 is a strong 72-inch four-drawer refrigerated chef base designed to withstand the demands of a busy kitchen. It features a heavy-duty stainless steel top insulated with a ceramic fabric layer, effectively eliminating melting foam and preventing heat transfer to the cabinet\'s interior. The top includes a standard marine edge on all sides, providing a 19-inch extension on each side, allowing cooking equipment to sit flat. The exterior construction consists of full stainless steel for durability, complemented by easy-to-mount casters, including six casters with two that are lockable, facilitating easy mobility. This model is front-breathing, making it ideal for tight spaces. The stainless steel drawer facings, linings, and frames are designed for longevity, with the top and bottom drawers capable of holding up to 69 deep pans. Each drawer is equipped with stainless steel hooked adapter bars and removable magnetic gaskets for easy cleaning. The heavy-duty Fulterer telescoping cartridge drawer system ensures smooth operation, while the self-contained capillary tube system uses environmentally friendly CFC-free refrigerant (R290). With an electronic thermostat featuring an external digital LED display for precise temperature control, the ARCB72 is designed for efficiency. The front-accessible condensing unit simplifies maintenance, and the evaporator coil is centered along the interior back of the cabinet. It meets NSF Standard 7 requirements for open food storage and comes with a full two-year parts and labor warranty, plus a five-year compressor warranty. The dimensions are 74 inches in width, 32 inches in depth, and 26 inches in height. Weight &amp; Dimensions Width: 74\\\" Depth: 32\\\" Height: 26\\\" Shipping Weight 355 lb.<\\/p>\",\"content\":\"<ul><li>Shipping weight of it is 355 lbs, indicating a strong construction suitable for heavy-duty use in commercial kitchens.<\\/li><li>It features a width of 74 inches, a depth of 32 inches, and a height of 26 inches, providing wide workspace and storage for food preparation.<\\/li><li>Operates on 6 amps, at 60 hertz, and requires a 1-phase power supply of 115 volts, ensuring compatibility with standard kitchen electrical systems.<\\/li><li>Has a capacity for 1\\/6 size food pans, accommodating up to 6 pans in its spacious drawers, making it ideal for efficient ingredient storage.<\\/li><li>It comes equipped with casters, allowing for easy movement and repositioning within the kitchen environment.<\\/li><li>Compressor is side-mounted, optimizing the unit\'s design for compact kitchen spaces while ensuring efficient operation.<\\/li><li>Uses a NEMA 5-15P plug type, facilitating straightforward electrical connections in commercial settings.<\\/li><li>Utilizes R-290 refrigerant, which is environmentally friendly and efficient, contributing to the unit\\u2019s low operational costs.<\\/li><li>It maintains a temperature range of 33 to 41 degrees Fahrenheit, ensuring optimal preservation of food items stored within.<\\/li><li>Constructed from stainless steel and aluminum, providing durability and ease of cleaning, while the marine edge top design prevents spills and simplifies maintenance.<br>&nbsp;<\\/li><\\/ul>\",\"warranty_information\":null,\"images\":[null,\"sssp-1\\/refrigerated-chef-bases-arcb72-new.jpg\",\"aub36r.webp\",\"arcb48.webp\"],\"product_type\":\"physical\",\"sale_type\":\"0\",\"sku\":\"ARCB72\",\"price\":\"4999\",\"sale_price\":\"3999\",\"start_date\":null,\"end_date\":null,\"unit_of_measurement_id\":\"1\",\"cost_per_item\":\"2304\",\"margin\":\"53.91%\",\"product_id\":\"1576\",\"barcode\":null,\"with_storehouse_management\":\"1\",\"quantity\":\"150\",\"allow_checkout_when_out_of_stock\":\"0\",\"stock_status\":\"in_stock\",\"discount\":[{\"product_quantity\":null,\"discount\":null,\"price_after_discount\":null,\"margin\":null,\"discount_from_date\":null,\"discount_to_date\":null},{\"product_quantity\":null,\"discount\":null,\"price_after_discount\":null,\"margin\":null,\"discount_from_date\":null,\"discount_to_date\":null}],\"weight_unit_id\":\"1\",\"weight\":\"355\",\"length_unit_id\":\"1\",\"length\":\"0\",\"depth\":\"32\",\"height\":\"26\",\"width\":\"29\",\"shipping_length_id\":\"1\",\"shipping_length\":\"0.00\",\"shipping_depth\":\"32.00\",\"shipping_height\":\"26.00\",\"shipping_width\":\"29.00\",\"is_added_attributes\":\"0\",\"has_product_options\":\"1\",\"deleted_videos\":null,\"specs\":[{\"name\":\"Manufacturer\",\"value\":\"Arctic Air\"},{\"name\":\"Model Number\",\"value\":\"ARCB72\"},{\"name\":\"Shipping Weight\",\"value\":\"355 lb.\"},{\"name\":\"Width\",\"value\":\"74 Inches\"},{\"name\":\"Depth\",\"value\":\"32 Inches\"},{\"name\":\"Height\",\"value\":\"26 Inches\"},{\"name\":\"Amps\",\"value\":\"6 Amps\"},{\"name\":\"Hertz\",\"value\":\"60 Hertz\"},{\"name\":\"Phase\",\"value\":\"1 Phase\"},{\"name\":\"Voltage\",\"value\":\"115 Volts\"},{\"name\":\"Capacity\",\"value\":\"1\\/6 Size Food Pans\"},{\"name\":\"Casters\",\"value\":\"Side Mounted\"},{\"name\":\"Compressor Location\",\"value\":\"1\\/3 HP\"},{\"name\":\"Plug Type\",\"value\":\"NEMA 5-15P\"},{\"name\":\"Refrigerant Type\",\"value\":\"R-290\"},{\"name\":\"Temperature Range\",\"value\":\"33 - 41 Degrees F\"},{\"name\":\"Top Type\",\"value\":\"Marine Edge\"},{\"name\":\"Access Type\",\"value\":\"Drawers\"},{\"name\":\"Base Style\",\"value\":\"Refrigerator\"},{\"name\":\"Construction\",\"value\":\"Stainless Steel and Aluminum\"},{\"name\":\"Full Size Food Pan Capacity\",\"value\":\"6 Pans\"},{\"name\":\"Number of Drawers\",\"value\":\"4 Drawers\"},{\"name\":\"Type\",\"value\":\"Chef Bases\"}],\"shipping_weight\":null,\"shipping_weight_option\":\"Kg\",\"titles