al results. Designed in an upright configuration, loading and unloading dishes are ergonomic and convenient, enhancing productivity during busy kitchen hours.<\\/p>\",\"warranty_information\":\"<p>No Warranty<\\/p>\",\"images\":[null,\"https:\\/\\/testhssite.com\\/storage\\/products\\/026-0090.0052_694651bd-98b5-4a04-87de-35a46f801f33.webp\"],\"product_type\":\"physical\",\"sale_type\":\"0\",\"sku\":\"026-0090.0052\",\"price\":\"9130.79\",\"sale_price\":null,\"start_date\":null,\"end_date\":null,\"unit_of_measurement_id\":\"1\",\"cost_per_item\":\"7189.6\",\"margin\":\"21.26%\",\"product_id\":\"1991\",\"barcode\":null,\"with_storehouse_management\":\"0\",\"quantity\":null,\"allow_checkout_when_out_of_stock\":\"0\",\"stock_status\":\"in_stock\",\"discount\":[{\"discount_id\":\"537\",\"product_quantity\":\"4\",\"discount\":\"5\",\"price_after_discount\":\"8674.25\",\"margin\":\"17.12\",\"discount_from_date\":\"2024-12-16T12:16\",\"discount_to_date\":\"2024-12-20T12:16\"},{\"discount_id\":\"538\",\"product_quantity\":\"8\",\"discount\":\"10\",\"price_after_discount\":\"8217.71\",\"margin\":\"12.51\",\"discount_from_date\":\"2024-12-16T12:16\",\"discount_to_date\":\"2024-12-20T12:16\"}],\"weight_unit_id\":\"1\",\"weight\":\"295\",\"length_unit_id\":\"1\",\"length\":\"0\",\"depth\":\"39\",\"height\":\"76\",\"width\":\"39\",\"shipping_length_id\":\"1\",\"shipping_length\":\"0.00\",\"shipping_depth\":\"0.00\",\"shipping_height\":\"0.00\",\"shipping_width\":\"0.00\",\"is_added_attributes\":\"0\",\"has_product_options\":\"1\",\"deleted_videos\":null,\"specs\":[{\"name\":\"Quantity\",\"value\":\"Each\\/1\"},{\"name\":\"Brand\",\"value\":\"American Dish\"},{\"name\":\"Model Number\",\"value\":\"American Dish AF-ES 3D\"},{\"name\":\"Shipping Weight\",\"value\":\"295 lb. 133.8 kg.\"},{\"name\":\"Shipping Volume (crated)\",\"value\":\"56.25 cu. ft. 1.59 cu meters\"},{\"name\":\"Height All closed Doors\",\"value\":\"71 1\\/2\\\" 181.6 cm\"},{\"name\":\"Height with Door\",\"value\"