 Per Cycle\"},{\"name\":\"Wash Heater\",\"value\":\"120\\u00b0F Min. or 49\\u00b0C Min.\"},{\"name\":\"ADC-44 Hot Temp Model Wash\",\"value\":\"160\\u00b0F\"},{\"name\":\"Model Wash\",\"value\":\"120\\u00b0F\"},{\"name\":\"Hot Temp Rinse\",\"value\":\"180\\u00b0F\"},{\"name\":\"Chemical Rinse\",\"value\":\"120\\u00b0F\"},{\"name\":\"Heating Wash\",\"value\":\"12 kW\"},{\"name\":\"Power Supply 1 Phase\",\"value\":\"115 V \\/ 50-60 Hz \\/ 1 PH\"},{\"name\":\"Total Cycle\",\"value\":\"90 - 120 - 150 Seconds\"},{\"name\":\"Water Temperature Supply\",\"value\":\"(NSF) 120\\u00b0F Min.\"}],\"shipping_weight\":null,\"shipping_weight_option\":\"Kg\",\"titles\":{\"4\":null,\"5\":null},\"variant_color_title\":\"Color\",\"variant_color_value\":null,\"variant_color_products\":null,\"variant_1_title\":null,\"variant_1_value\":null,\"variant_1_products\":null,\"variant_2_title\":null,\"variant_2_value\":null,\"variant_2_products\":null,\"variant_3_title\":null,\"variant_3_value\":null,\"variant_3_products\":null,\"compare_type\":null,\"compare_products\":null,\"faq_schema_config\":[[{\"key\":\"question\",\"value\":null},{\"key\":\"answer\",\"value\":null}]],\"seo_meta\":{\"seo_title\":null,\"seo_description\":null,\"index\":\"index\"},\"seo_meta_image\":null,\"language\":\"en_US\",\"status\":\"pending\",\"store_id\":\"16\",\"is_featured\":\"1\",\"categories\":[\"1\",\"65\",\"227\",\"109\",\"380\"],\"brand_id\":\"19\",\"product_collections\":[\"1\",\"2\"],\"minimum_order_quantity\":\"4\",\"maximum_order_quantity\":\"0\",\"tag\":null,\"producttypes\":\"[{\\\"value\\\":\\\"Low Temperature Undercounter\\\"}]\",\"frequently_bought_together\":\"[{\\\"value\\\":\\\"64910K\\\"},{\\\"value\\\":\\\" SSTW-2424\\\"},{\\\"value\\\":\\\" C-RB261\\\"}]\",\"variant_requires_shipping\":\"0\",\"refund\":\"non-refundable\",\"google_shopping_category\":null,\"delivery_days\":null,\"google_shopping_mpn\":null,\"box_quantity\":null,\"submitter\":\"apply\",\"documents\":[{}]}', 'updated', 'Mozilla/5.0 