(9401, 1, 'product', '{\"name\":\"American Dish L-90-3DWS-3D 3-Door Upright Single Rack Dish Machine\",\"model\":\"Botble\\\\Ecommerce\\\\Models\\\\Product\",\"slug\":\"name-225\",\"slug_id\":\"3071\",\"is_slug_editable\":\"1\",\"description\":\"<p>The upright dish machine boasts convenient top mount controls, providing easy access for operators to manage the washing process efficiently. With a generous door clearance of 20.375 inches, loading and unloading dishes is made effortless, accommodating various dish sizes and shapes. Equipped with a quick-service 1 1\\/2 HP pump, this dishwasher ensures swift maintenance and repairs, minimizing downtime in busy kitchen environments. Additionally, its quick-release spray arms facilitate easy cleaning and maintenance, promoting optimal performance with minimal hassle. Constructed with durable stainless steel components, including an air gap, impellor, and sump, the dishwasher promises longevity and reliability. Its low-energy dump and fill system contribute to energy efficiency without compromising on cleaning effectiveness. The exterior-mounted chemical pump heads and two-stage filter safeguard the pump and spray jets, ensuring consistent performance over time. With a water consumption rate of 1.2 gallons per rack and a 90-second cycle time, this dishwasher achieves high throughput, capable of handling up to 37 racks per hour. The innovative design features a true 3-door configuration, with only two doors opening in either arrangement, minimizing water splash and maintaining door alignment. Additional features such as an eye-level temperature gauge, built-in de-liming switch, and automatic chemical feed further enhance usability and maintenance ease, making it an ideal choice for commercial kitchen operations.<\\/p>\",\"content\":\"<p>The dishwasher is equipped with a three-door configuration, facilitating efficient loading and unloading of dishes. Featuring an upright layout, this dishwasher optimizes space utilization in the kitchen while accommodating a single rack of dishes. Operating at low temperatures, this dishwasher ensures energy efficiency while effectively cleaning and sanitizing dishes. Designed with a pass-through configuration, this dishwasher allows for seamless transfer of racks from one side to the other. Equipped with a single chemical alarm, this dishwasher provides notification in case of any chemical-related issues during the washing cycle.<\\/p>\",\"warranty_information\":\"<p>No Warranty<\\/p>\",\"images\":[null,\"https:\\/\\/testhssite.com\\/storage\\/products\\/024-1090.0422_f03e4ad0-3482-4b64-bd04-0ba6fe95239d.webp\"],\"product_type\":\"physical\",\"sale_type\":\"0\",\"sku\":\"024-1090.0422\",\"price\":\"6159.37\",\"sale_price\":null,\"start_date\":null,\"end_date\":null,\"unit_of_measurement_id\":\"1\",\"cost_per_item\":\"4849.9\",\"margin\":\"21.26%\",\"product_id\":\"1943\",\"barcode\":null,\"with_storehouse_management\":\"0\",\"quantity\":null,\"allow_checkout_when_out_of_stock\":\"0\",\"stock_status\":\"in_stock\",\"discount\":[{\"discount_id\":\"441\",\"product_quantity\":\"4\",\"discount\":\"5\",\"price_after_discount\":\"5851.40\",\"margin\":\"17.12\",\"discount_from_date\":\"2024-12-16T12:16\",\"discount_to_date\":\"2024-12-20T12:16\"},{\"discount_id\":\"442\",\"product_quantity\":\"8\",\"discount\":\"10\",\"price_after_discount\":\"5543.43\",\"margin\":\"12.51\",\"discount_from_date\":\"2024-12-16T12:16\",\"discount_to_date\":\"2024-12-20T12:16\"}],\"weight_unit_id\":\"1\",\"weight\":\"300\",\"length_unit_id\":\"1\",\"length\":\"0\",\"depth\":\"28\",\"height\":\"74\",\"width\":\"29\",\"shipping_length_id\":\"1\",\"shipping_length\":\"0.00\",\"shipping_depth\":\"0.00\",\"shipping_height\":\"0.00\",\"shipping_width\":\"0.00\",\"is_added_attributes\":\"0\",\"has_product_options\":\"1\",\"deleted_videos\":null,\"specs\":[{\"name\":\"Quantity\",\"value\":\"1\\/Each\"},{\"name\":\"Brand\",\"value\":\"American Dish\"},{\"name\":\"Model Number\",\"value\":\"L-90-3DWS-3D\"},{\"name\":\"Shipping Weight\",\"value\":\"300 Lbs. (136.1 Kgs)\"},{\"name\":\"Shipping Dimensions\",\"value\":\"36\\\" L x 36\\\" W x 78\\\" H\"},{\"name\":\"Height (Adjuster Feet Will Give)\",\"value\":\"Min: 70.5\\\" - Max: 71.48\"},{\"name\":\"Width (Overall)\",\"value\":\"29\\\" (73.6 cm)\"},{\"name\":\"Width Table to Table\",\"value\":\"25\\\" (63.5 cm)\"},{\"name\":\"Depth\",\"value\":\"28\\\" (71.1 cm)\"},{\"name\":\"Access Door Clearance\",\"value\":\"20.375\\\" Tall - 20.5\\\" Wide (51.75 x 52.07 cm)\"},{\"name\":\"Rack Clearance (Through Machine)\",\"value\":\"Standard 19.75\\\" x 19.75\\\" (50.2 x 52.07 cm)\"},{\"name\":\"Water Inlet\",\"value\":\"(1\\/2\\\") F.P.T\"},{\"name\":\"Drain Size\",\"value\":\"(2\\\")\"},{\"name\":\"NSF Rated Capacity\",\"value\":\"37 racks\\/hour\"},{\"name\":\"Wash HP\",\"value\":\"1.5 Hp\"},{\"name\":\"Gal per rack\",\"value\":\"1.2 gallons per cycle or 4.54 liters per cycle\"},{\"name\":\"Wash Heater\",\"value\":\"160\\u00b0F\"},{\"name\":\"ADC-44 Hot Temp Model Wash\",\"value\":\"120\\u00b0F\"},{\"name\":\"Model Wash\",\"value\":\"180\\u00b0F\"},{\"name\":\"Hot Temp Rinse\",\"value\":\"120\\u00b0F\"},{\"name\":\"Heating Wash\",\"value\":\"12 kW\"},{\"name\":\"Power Supply 1 Phase\",\"value\":\"115 V \\/ 1 HP \\/ 20 Amp\"},{\"name\":\"Total Cycle\",\"value\":\"90 Seconds\"},{\"name\":\"Water Temperature Supply\",\"value\":\"120\\u00b0F Minimum.\"}],\"shipping_weight\":null,\"shipping_weight_option\":\"Kg\",\"titles\":{\"4\":null,\"5\":null},\"variant_color_title\":\"Color\",\"variant_color_value\":null,\"variant_color_products\":null,\"variant_1_title\":null,\"variant_1_value\":null,\"variant_1_products\":null,\"variant_2_title\":null,\"variant_2_value\":null,\"variant_2_products\":null,\"variant_3_title\":null,\"variant_3_value\":null,\"variant_3_products\":null,\"compare_type\":null,\"compare_products\":null,\"faq_schema_config\":[[{\"key\":\"question\",\"value\":null},{\"key\":\"answer\",\"value\":null