ne year warranty on all oven motors<\\/p>\",\"images\":[null,\"https:\\/\\/testhssite.com\\/storage\\/products\\/XAF-193.webp\"],\"product_type\":\"physical\",\"sale_type\":\"0\",\"sku\":\"XAF-193\",\"price\":\"2750\",\"sale_price\":null,\"start_date\":null,\"end_date\":null,\"unit_of_measurement_id\":\"1\",\"cost_per_item\":\"2500\",\"margin\":\"9.09%\",\"product_id\":\"2418\",\"barcode\":null,\"with_storehouse_management\":\"0\",\"quantity\":null,\"allow_checkout_when_out_of_stock\":\"0\",\"stock_status\":\"in_stock\",\"discount\":[{\"discount_id\":\"1407\",\"product_quantity\":\"4\",\"discount\":\"5\",\"price_after_discount\":\"2612.50\",\"margin\":\"4.31\",\"discount_from_date\":\"2024-12-16T12:16\",\"discount_to_date\":\"2024-12-20T12:16\"},{\"discount_id\":\"1408\",\"product_quantity\":\"8\",\"discount\":\"10\",\"price_after_discount\":\"2475.00\",\"margin\":\"-1.01\",\"discount_from_date\":\"2024-12-16T12:16\",\"discount_to_date\":\"2024-12-20T12:16\"}],\"weight_unit_id\":\"1\",\"weight\":\"190\",\"length_unit_id\":\"1\",\"length\":\"0\",\"depth\":\"32\",\"height\":\"23\",\"width\":\"32\",\"shipping_length_id\":\"1\",\"shipping_length\":\"0.00\",\"shipping_depth\":\"0.00\",\"shipping_height\":\"0.00\",\"shipping_width\":\"0.00\",\"is_added_attributes\":\"0\",\"has_product_options\":\"1\",\"deleted_videos\":null,\"specs\":[{\"name\":\"Quantity\",\"value\":\"1\\/Each\"},{\"name\":\"Shipping Weight\",\"value\":\"190 lb.\"},{\"name\":\"Width\",\"value\":\"31 1\\/2 Inches\"},{\"name\":\"Depth\",\"value\":\"32 Inches\"},{\"name\":\"Height\",\"value\":\"23 Inches\"},{\"name\":\"Interior Width\",\"value\":\"27 1\\/4 Inches\"},{\"name\":\"Interior Depth\",\"value\":\"18 3\\/4 Inches\"},{\"name\":\"Interior Height\",\"value\":\"13 Inches\"},{\"name\":\"Amps\",\"value\":\"24.6 Amps\"},{\"name\":\"Hertz\",\"value\":\"60 Hz\"},{\"name\":\"Phase\",\"value\":\"1 Phase\"},{\"name\":\"Voltage\",\"value\":\"208 - 240 Volts\"},{\"name\":\"Wattage\",\"value\":\"5.9 Kilowatts\"},