ation-settings:inherit;font-weight:inherit;line-height:inherit;list-style:disc;margin-bottom:0px;margin-right:0px;margin-top:0px;padding:0px;vertical-align:baseline;\\\" data-mce-fragment=\\\"1\\\"><span style=\\\"border-width:0px;box-sizing:border-box;font-family:inherit;font-feature-settings:inherit;font-kerning:inherit;font-optical-sizing:inherit;font-size-adjust:inherit;font-size:14px;font-stretch:inherit;font-style:inherit;font-variant:inherit;font-variation-settings:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;vertical-align:baseline;\\\" data-mce-fragment=\\\"1\\\">They are responsible for managing&nbsp;<\\/span><a style=\\\"border-width:0px;box-sizing:border-box;color:var(--link-color);font-family:inherit;font-feature-settings:inherit;font-kerning:inherit;font-optical-sizing:inherit;font-size-adjust:inherit;font-size:14px;font-stretch:inherit;font-style:inherit;font-variant:inherit;font-variation-settings:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;text-decoration:none;touch-action:manipulation;transition:0.25s;vertical-align:baseline;\\\" href=\\\"https:\\/\\/horecastore.ae\\/collections\\/housekeeping-trolley-1\\\" title=\\\"Housekeeping Trolley\\\" aria-describedby=\\\"a11y-new-window-external-message\\\" data-mce-fragment=\\\"1\\\" data-mce-href=\\\"https:\\/\\/horecastore.ae\\/collections\\/housekeeping-trolley-1\\\" target=\\\"_blank\\\"><span style=\\\"border-width:0px;box-sizing:border-box;font-family:inherit;font-feature-settings:inherit;font-kerning:inherit;font-optical-sizing:inherit;font-size-adjust:inherit;font-size:14px;font-stretch:inherit;font-style:inherit;font-variant:inherit;font-variation-settings:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;vertical-align:baseline;\\\" data-mce-fragment=\\\"1\\\">housekeeping<\\/span><\\/a><span style=\\\"border-width:0px;box-sizing:border-box;font-family:inherit;font-feature-settings:inherit;font-kerning:inherit;font-optical-