tion.<br>\n\nOffers adjustable shelves for flexible storage configurations, accommodating a variety of food items and packaging sizes.\n', 'pending', '[\"https:\\/\\/testhssite.com\\/storage\\/products\\/MBF8005GR_73da5ae7-5af3-477f-85c1-a56dbeb63ad1.webp\"]', 'MBF8005GR', 0, NULL, 0, 0, 1, 14, 0, 0, 3093, NULL, NULL, NULL, NULL, NULL, 52.00, NULL, 81.00, NULL, 32.00, NULL, 390.00, NULL, NULL, 0, '2024-12-13 12:35:07', '2024-12-13 14:14:00', 'in_stock', 1, 'Botble\\ACL\\Models\\User', 'https://testhssite.com/storage/products/MBF8005GR_73da5ae7-5af3-477f-85c1-a56dbeb63ad1.webp', 'physical', '', 2077, 4, 0, 8, 0, 'Two Year Parts & Labor Warranty', NULL, NULL, '', NULL, '', '', 0, NULL, NULL, '', 0, '', '', '', '', NULL, NULL, NULL, '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{\"value\":\"64910K\"},{\"value\":\" SSTW-2424\"},{\"value\":\" C-RB107\"}]', '[]', '[]', NULL, '', NULL, '', '', '', '', '', '', '', '', '', '', '', '');
