(1865, 'Migali C-CB52-60-HC 52\" Wide Chef Base Refrigerator', '\n<p>The Migali® C-CB52-60 refrigerated chef base is designed to enhance cooking efficiencies with its versatile features. It offers a refrigerated drawer section that can hold up to 18 1/6th size pans, and a spacious 60” top that supports up to 717 lbs of countertop cooking equipment. Engineered with a robust forced air refrigeration system, it ensures cold, uniform temperatures throughout the interior. The unit incorporates a digital controller and temperature read-out, enhancing temperature consistency and energy efficiency. Its high polished stainless steel exterior and interior, along with recessed drawer handles, provide both an ergonomic and aesthetically pleasing design.</p>', '\n\nRefrigerated drawer section for up to 18 1/6th size pans<br>\n\nExpanded 60” top supporting up to 717 lbs of cooking equipment<br>\n\nRobust forced air refrigeration system for uniform temperatures<br>\n\nDigital controller and temperature read-out for consistency and efficiency<br>\n\nHigh polished stainless steel design with recessed drawer handles\n', 'pending', '[\"https:\\/\\/testhssite.com\\/storage\\/products\\/C-CB52-60-HC_9ff9ee4d-f4e7-4a91-82ba-95e2e32a3381.webp\"]', 'C-CB52-60-HC', 0, NULL, 0, 0, 1, 30, 0, 0, 2728, NULL, NULL, NULL, NULL, NULL, 61.00, NULL, 27.00, NULL, 32.00, NULL, 556.00, NULL, NULL, 0, '2024-12-13 12:36:18', '2024-12-13 14:14:06', 'in_stock', 1, 'Botble\\ACL\\Models\\User', 'https://testhssite.com/storage/products/C-CB52-60-HC_9ff9ee4d-f4e7-4a91-82ba-95e2e32a3381.webp', 'physical', '', 2090, 4, 0, 22, 0, 'Five Years Compressor Warranty', NULL, NULL, '', NULL, '', '', 0, NULL, NULL, '', 0, '', '', '', '', NULL, NULL, NULL, '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{\"value\":\"64910K\"},{\"value\":\" SSTW-2424\"},{\"value\":\" C-RB173\"}]', '[]', '[]', NULL, '', NULL, '', '', '', '', '', '', '', '', '', '', '', ''),
