(1912, 'Migali C-1F-LHH-HC Top Mount Reach-In Single Door 23 cu/ft Freezer', '\n<p>The Migali® C-1F reach-in freezer is an ideal solution for storing various types of food in a commercial kitchen. It features a robust forced air refrigeration system that ensures cold, uniform temperatures throughout the cabinet\'s interior. This model includes a digital controller and temperature read-out for precise temperature management, improved energy efficiency, and superior performance. The C-1F is both visually appealing and ergonomic, with a high-polished stainless steel exterior and interior, rounded door edges, and a recessed door handle. The spacious 23 cu/ft interior includes three adjustable shelves, with the option to add a bun rack for 18?x 26? sheet pans or 12?x 20? hotel pans.</p>', '\n\nRobust forced air refrigeration system for uniform temperatures<br>\n\nDigital controller and temperature read-out for precise management<br>\n\nHigh-polished stainless steel exterior and interior with rounded door edges<br>\n\nSpacious 23 cu/ft interior with three adjustable shelves<br>\n\nOptional bun rack for accommodating various pan sizes\n', 'published', '[\"https:\\/\\/testhssite.com\\/storage\\/products\\/C-1F-LHH-HC_bc2cf41c-e60b-4546-a9c3-6eb43fcb0cc2.webp\"]', 'C-1F-LHH-HC', 0, NULL, 0, 0, 1, 30, 0, 0, 2473, NULL, NULL, NULL, NULL, NULL, 29.00, NULL, 83.00, NULL, 33.00, NULL, 294.00, NULL, NULL, 0, '2024-12-13 12:37:11', '2024-12-30 07:49:52', 'in_stock', 1, 'Botble\\ACL\\Models\\User', 'https://testhssite.com/storage/products/C-1F-LHH-HC_bc2cf41c-e60b-4546-a9c3-6eb43fcb0cc2.webp', 'physical', '', 1894, 4, 0, 22, 0, 'Five Years Compressor Warranty', NULL, NULL, '', NULL, '', '', 0, NULL, NULL, '', 0, '', '', '', '', NULL, NULL, NULL, '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{\"value\":\"64910K\"},{\"value\":\" SSTW-2424\"},{\"value\":\" C-RB220\"}]', '[]', '[]', NULL, '', NULL, '', '', '', '', '', '', '', '', '', '', '', ''),
(1913, 'Migali C-1F-HC Top Mount Reach-In Single Door 23 cu/ft  Freezer', '<p>The Migali® C-1F reach-in freezer is ideal for storing various types of food in a commercial kitchen. This series features a robust forced air refrigeration system, ensuring cold, uniform temperatures throughout the cabinet. It includes a digital controller and temperature read-out for precise temperature management, enhanced energy efficiency, and superior performance. The C-1F is visually appealing and ergonomic, with a high-polished stainless steel exterior and interior, rounded door edges, and a recessed handle. Its 23 cu/ft interior is spacious and equipped with 3 adjustable shelves, with an optional bun rack for 18?x 26? sheet pans or 12?x 20? hotel pans also available.</p>', '<p>Robust forced air refrigeration system<br>Digital controller and temperature read-out<br>High-polished stainless steel exterior and interior<br>23 cu/ft interior with 3 adjustable shelves<br>Optional bun rack for 18?x 26? sheet pans or 12 by 20 hotel pans</p>', 'published', '[\"https:\\/\\/testhssite.com\\/storage\\/products\\/C-1F-HC_1023e522-6121-4d09-8042-ec172fe21da2.webp\"]', 'C-1F-HC', 0, NULL, 0, 0, 1, 30, 0, 0, 2473, NULL, NULL, NULL, 0.00, 1, 29.00, NULL, 83.00, NULL, 33.00, NULL, 294.00, 1, NULL, 0, '2024-12-13 12:37:11', '2024-12-30 07:49:52', 'in_stock', 1, 'Botble\\ACL\\Models\\User', 'https://testhssite.com/storage/products/C-1F-HC_1023e522-6121-4d09-8042-ec172fe21da2.webp', 'physical', NULL, 1894, 4, 0, 22, 0, '<p>Five Years Compressor Warranty</p>', NULL, NULL, '', NULL, '', '', 0, NULL, 1, '', 0, '', '', NULL, NULL, NULL, '{\"1\":{\"title\":\"Manual\",\"path\":\"products\\/documents\\/96azYGwGVr2NWVNygaOAYmYiLuItsbKrtfeYTohh.pdf\"},\"2\":{\"title\":\"Warranty\",\"path\":\"products\\/documents\\/aOi6yW0WPfbgAVNB2xvZZZyMGjFS21FUifIE35m3.pdf\"},\"3\":{\"title\":\"Brochure\",\"path\":\"products\\/documents\\/PYNxbuT0AyzwhFwyTI27g69RTK2zHUhi234WXnLD.pdf\"}}', NULL, '[]', 0, NULL, 'Kg', NULL, NULL