ublished', '[\"https:\\/\\/testhssite.com\\/storage\\/products\\/EPR3_c43d00a3-afff-4a03-a971-a8a5a66659f4.webp\"]', 'EPR3', 0, NULL, 0, 0, 1, 28, 0, 0, 4210, NULL, NULL, NULL, 71.00, NULL, NULL, NULL, 38.00, NULL, 32.00, NULL, 456.00, NULL, NULL, 0, '2024-12-13 12:47:53', '2024-12-16 08:19:21', 'in_stock', 1, 'Botble\\ACL\\Models\\User', 'https://testhssite.com/storage/products/EPR3_c43d00a3-afff-4a03-a971-a8a5a66659f4.webp', 'physical', '', 3608, 4, 0, 20, 0, 'Five year compressor & 3 Year parts warranty', NULL, NULL, '', NULL, '', '', 0, NULL, NULL, '', 0, '', '', '', '', NULL, NULL, NULL, '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{\"value\":\"64910K\"},{\"value\":\" SSTW-2424\"},{\"value\":\" C-RB504\"}]', '[]', '[]', NULL, '', NULL, '', '', '', '', '', '', '', '', '', '', '', '');
