INSERT INTO `ec_product_categories` (`id`, `name`, `parent_id`, `description`, `status`, `order`, `image`, `is_featured`, `created_at`, `updated_at`, `icon`, `icon_image`, `slug`) VALUES
(1, 'Kitchen Equipment', 0, NULL, 'published', 0, 'buffet-and-food-displays-4/kitchen-equipment.webp', 0, '2024-05-29 21:30:36', '2024-12-30 13:47:11', '0', 'buffet-and-food-displays-4/kitchen-equipment.webp', 'kitchen-equipment'),
(40, 'Cooking Equipment', 1, '<p>This is testing&nbsp;</p>', 'published', 0, 'buffet-and-food-displays-4/cooking-equipment.png', 0, '2024-10-03 14:09:06', '2024-12-30 13:18:53', 'fab fa-adn', 'buffet-and-food-displays-4/cooking-equipment.png', 'cooking-equipment'),
(42, 'Food Preparation Equipment', 1, '<p>Test</p>', 'published', 1, 'food-preparation-equipment.webp', 1, '2024-10-15 10:35:29', '2024-11-01 12:43:41', '0', NULL, 'food-preparation-equipment'),
(44, 'Preparation Tables', 1, NULL, 'published', 2, 'preparation-tables.webp', 0, '2024-10-16 08:49:57', '2024-11-01 12:43:41', '0', NULL, 'preparation-tables'),
(45, 'Refrigeration', 0, '<p>Introducing our commercial refrigeration solutions, made to suit all kinds of foodservice businesses. Whether you run a café, bakery, corner shop, hotel or restaurant, our commercial refrigeration options are here to help you win over your clients and succeed your business.</p><p>From keeping perishables fresh to displaying tempting treats, our products ensure your kitchen runs smoothly. We offer a wide range of refrigeration products, including ice machines, milk coolers, soft-serve ice cream machines, salad counter top prep units, and more! If you can think of it, we have it!</p><p>We also make an effort to carefully select brands that are not only reliable but also long-lasting for our clients. Brands like Ice-o-matic, Hoshizaki, Southbend, Arctic Air are some of our major suppliers. Dive into our diverse variety of modern and innovative designs to make your display impactful, preserve natural food flavors, keep everything cool and fresh while giving you maximum storage!<br>&nbsp;</p>', 'published', 1, 'buffet-and-food-displays-4/refrigeration-2.webp', 1, '2024-10-16 08:59:06', '2024-12-30 13:53:43', 'fab fa-500px', 'buffet-and-food-displays-4/refrigeration-2.webp', 'refrigeration'),
(46, 'Commercial Refrigerator', 45, '<p>Enhance your business with our wide range of commercial refrigerators from top brands like Hoshizaki, Beverage Air, True, and more. Choose from single and double-door options, including space-efficient undercounter units and classic upright models, tailored to meet your specific requirements and budget. Ensure your ingredients stay fresh and your operations run seamlessly with our durable refrigerators and chillers. Explore our selection today to find the ideal refrigeration system for your kitchen!</p>', 'published', 0, 'buffet-and-food-displays-4/commercial-refrigerator.webp', 0, '2024-10-16 09:01:09', '2024-12-30 14:58:16', 'fab fa-500px', NULL, 'commercial-refrigerator'),
(47, 'Chef Base Refrigerators', 46, NULL, 'published', 5, 'chef-base-refrigerators-4f28fddd-7ddb-4a4d-a627-48fe0d965cb4.webp', 0, '2024-10-16 09:01:53', '2024-11-01 12:43:41', '0', NULL, 'chef-base-refrigerators'),
