INSERT INTO `posts` (`id`, `name`, `description`, `content`, `status`, `author_id`, `author_type`, `is_featured`, `image`, `views`, `format_type`, `created_at`, `updated_at`) VALUES
(13, 'The Jeddah Tower: Will It Ever Rise?', '', '<figure class=\"image\"><img style=\"aspect-ratio:1200/468;\" src=\"https://admin.horecastore.sa/storage/the-jeddah-tower-will-it-ever-rise.webp\" alt=\"the-jeddah-tower-will-it-ever-rise.webp\" width=\"1200\" height=\"468\"></figure><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Back in 2008, Saudi Arabia\'s billionaire investor, Prince Alwaleed Bin Talal, declared his intent to construct the world\'s tallest skyscraper, reaching a staggering height of over 3,280 feet (about 999.74 m). This ambitious project, the Jeddah Tower, was destined to be the centerpiece of Jeddah Economic City, aspiring to be Saudi Arabia\'s answer to Dubai, boasting a height twice that of the One World Trade Center in the U.S.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">However, construction on this record-breaking tower hit a roadblock in 2018 due to Saudi political turmoil and the COVID-19 pandemic. As of fall 2023, only one-third of the tower has been completed, but construction is set to resume. The Jeddah Economic Company\'s website proudly announces, \"It\'s Happening,\" but the question remains: when will it be completed?&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-size:24px;\"><b style=\"font-family:inherit;font-size:24px;font-style:inherit;line-height:inherit;margin:0px;padding:0px;\"><span style=\"font-family:inherit;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\"><strong>Jeddah Economic City - The Next Dubai?</strong></span><strong>&nbsp;</strong></b><span style=\"font-family:inherit;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\"><strong> &nbsp;</strong></span>&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Dubai\'s Burj Khalifa, standing at 2,717 feet (about 828.14 m), currently holds the title of the world\'s tallest building. Designed by American architect Adrian Smith, the Burj Khalifa epitomized Dubai\'s grand vision, becoming the centerpiece of an impressive urban development. This achievement in urban planning and architecture has garnered praise from Antony Wood, president of the Council on Tall Buildings and Urban Habitat.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">When Prince Alwaleed set his sights on constructing the world\'s first kilometer-high tower, Dubai\'s Burj Khalifa was still under construction. The aim from the start was to replicate Dubai\'s success in Saudi Arabia, making Jeddah Economic City a futuristic metropolis along the Red Sea, featuring the towering Jeddah Tower.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Architect Adrian Smith, who designed both the Burj Khalifa and the Jeddah Tower, implemented similar design elements, notably their \"megatall\" status (exceeding 1,968.5 feet) and a Y-shaped plan with three exterior walls, proven to be more aerodynamic and wind-resistant at extreme heights. While the Burj Khalifa tapers gradually, the Jeddah Tower boasts a continuous tapering design, piercing the clouds like a colossal needle.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-size:24px;\"><b style=\"font-family:inherit;font-size:24px;font-style:inherit;line-height:inherit;margin:0px;padding:0px;\"><span style=\"font-family:inherit;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\"><strong>What Does the Tower Include?</strong></span><strong>&nbsp;</strong></b><span style=\"font-family:inherit;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\"><strong> &nbsp;</strong></span>&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">The most talked-about feature of the Jeddah Tower is its open-air observation deck, positioned at a staggering 2,187 feet (about 666.6 m), making it the world\'s highest. Initially intended as a helipad, safety concerns due to unpredictable desert winds led to its redesign. If built to its original specifications, the tower will require a colossal 80,000 tons of steel and will be serviced by 59 elevators (including five double-decker cars) and 12 escalators. The tower\'s lower third will house office space, followed by a luxury hotel, with the highest floors designated for apartments, including a massive penthouse.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">A Rocky Start for the Kingdom Tower Construction of the Jeddah Tower, initially named the Kingdom Tower, commenced on April 1, 2013, with over a year spent laying its massive foundation, featuring concrete pilings exceeding 10 feet in diameter and the length of a football field. Above-ground construction started in September 2014.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">However, in 2017, a political crisis shook Saudi Arabia when Crown Prince Mohammed bin Salman initiated a widespread anti-corruption crackdown. Several prominent figures, including the primary financial backer of the Jeddah Tower, Prince Alwaleed bin Talal, were detained. Although they were later released after paying hefty fines, this turmoil disrupted construction. In 2018, work on the Jeddah Tower resumed, targeting a 2020 completion date. Labor issues with a contractor in late 2018 and the onset of the COVID-19 pandemic halted construction again. As of 2021, the tower\'s base stands at a third of its planned height, but there\'s hope for progress soon.&nbsp;</span></p><h2 style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-size:24px;font-style:normal;line-height:1.4;margin:0px;padding:0px;word-spacing:0px;\"><span style=\"font-size:24px;\"><b style=\"font-family:inherit;font-size:24px;font-style:inherit;line-height:inherit;margin:0px;padding:0px;\"><span style=\"font-family:inherit;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\"><strong>The Future of the Jeddah Tower</strong></span><strong>&nbsp;</strong></b><span style=\"font-family:inherit;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\"><strong>&nbsp;</strong></span>&nbsp;</span></h2><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Despite its status, experts like Antony Wood remain optimistic about the Jeddah Tower. Wood, who visited the construction site in 2018, praised the project\'s scale and ambition. He believes that the project will eventually be completed, as it would be an embarrassment not to finish it. However, it\'s uncertain whether it will adhere to its original design or become the world\'s tallest building.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">To Wood, the intermittent construction process is unique, representing a project that stopped rather than simply falling behind schedule. Recent news of construction resuming validates this optimism, although a new completion timeline remains undecided.&nbsp;&nbsp;</span></p><h2 style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-size:24px;font-style:normal;line-height:1.4;margin:0px;padding:0px;word-spacing:0px;\"><span style=\"font-size:24px;\"><b style=\"font-family:inherit;font-size:24px;font-style:inherit;line-height:inherit;margin:0px;padding:0px;\"><span style=\"font-family:inherit;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\"><strong>The Race for the World\'s Highest Observatory</strong></span><strong>&nbsp;</strong></b><span style=\"font-family:inherit;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\"><strong>&nbsp;</strong></span>&nbsp;</span></h2><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Interestingly, competition for the world\'s highest observatory isn\'t limited to the Jeddah Tower, with Emaar\'s Dubai project also vying for the title, albeit facing its own delays due to the pandemic.&nbsp;</span></p>', 'published', 1, 'Botble\\ACL\\Models\\User', 0, 'products/the-jeddah-tower-will-it-ever-rise.webp', 1, NULL, '2024-12-24 06:11:52', '2024-12-24 06:13:13'),
(14, 'Dubai Safari Park Announces Start Date for New Season', '', '<figure class=\"image\"><img style=\"aspect-ratio:1200/468;\" src=\"https://admin.horecastore.sa/storage/dubai-safari-park-announces-start-date-for-new-season.webp\" alt=\"dubai-safari-park-announces-start-date-for-new-season.webp\" width=\"1200\" height=\"468\"></figure><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\"><strong style=\"font-family:inherit;font-size:14px;font-style:inherit;line-height:inherit;margin:0px;padding:0px;\">This season will offer an amazing lineup of new productions, talks, events, and workshops.</strong></span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">On October 5, the Dubai Safari Park will reopen for the 2023-24 season, bringing back its animal experience. The attraction\'s website is currently accepting reservations.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">The \'bird kingdom\' show, Asian Village\'s exhibit introducing guests to some of the world\'s most interesting wildlife, and a bird of prey show are among the attractions this season.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">The 3,000 creatures in the 119-hectare park include 78 species of mammals (including 10 carnivores and 17 primates), 50 types of reptiles, 111 varieties of birds, amphibians, and invertebrates. The park, which is closed during the summer, allows visitors to see animals and birds in their natural habitats.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">The park, which is overseen by the Dubai Municipality, saw over 500,000 visitors last year.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">The park is divided into five sections: the African Village, the Asian Village, the Arabian Desert Safari, the Explorer Village, and the Valley. A day pass and a safari tour are available, with prices ranging from Dh50 to Dh110 per adult.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Special bundles include:&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">- King of safari: Led by a skilled guide who will give insights about the park\'s numerous animal species.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">- Behind the scenes: It provides a 90-minute behind-the-scenes encounter to learn about the daily care services offered to the animals.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">- Jungle capture: It will give three exclusive hours for guests to photograph animals from various spots across the park.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">- Dine in the wild: It allows tourists to have their favorite meal in the middle of the park.</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Visitors may also participate in special feeding sessions for giraffes and rhinos.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">According to Ahmed Al Zarooni, director of Dubai Municipality\'s Department of Public Parks and Recreational Facilities, \"in the upcoming 2023-24 season, Dubai Safari Park will offer a multitude of engaging activities that seamlessly blend entertainment and education while introducing a diverse array of animals and birds that inhabit the park.\"&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">\"Visitors will have the unique opportunity to learn about the park\'s distinctive ecosystem and its commitment to maintaining the ideal living conditions for its resident species, ensuring their well-being in accordance with the highest health standards.\"</span></p>', 'published', 1, 'Botble\\ACL\\Models\\User', 0, 'products/dubai-safari-park-announces-start-date-for-new-season-1.webp', 0, NULL, '2024-12-24 06:14:46', '2024-12-24 06:14:53'),
(15, 'Cabinet announces public holidays in the UAE for 2024', '', '<figure class=\"image\"><img style=\"aspect-ratio:1200/468;\" src=\"https://admin.horecastore.sa/storage/cabinet-announces-public-holidays-in-the-uae-for-2024.webp\" alt=\"cabinet-announces-public-holidays-in-the-uae-for-2024.webp\" width=\"1200\" height=\"468\"></figure><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">National holidays for the public and private sectors in 2024 have been proclaimed by the UAE Cabinet.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">New Year\'s Day, which falls on the first public holiday of 2024, will be followed by Eid Al Fitr, the celebration of the conclusion of Ramadan.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">The Gregorian dates of some holidays, which are based on the Islamic Hijri calendar, are determined by moon sightings.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">This indicates that a timeframe of two to three days will encompass these vacations.</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Arafat Day might fall on Saturday, June 15, 2024, while Eid Al Fitr could occur between Monday, April 8, and Thursday, April 11.</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Sunday, June 16 is a possible date for Eid Al Adha, which is observed between Monday, June 17, and Tuesday, June 18.</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">The Islamic New Year may, nevertheless, occur on Sunday, June 7, 2024.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Sunday, September 15, might possibly be Prophet Mohammed\'s birthday.&nbsp;</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;word-spacing:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Meanwhile, National Day, which comes on December 2 and 3, will be the following public holiday for this year.</span></p><div class=\"twitter-tweet twitter-tweet-rendered\" style=\"background-color:rgb(255,255,255);color:rgb(0,0,0);font-family:Montserrat;font-size:14px;font-style:normal;font-weight:400;line-height:inherit;margin:0px;padding:0px;word-spacing:0px;\"><h3 style=\"font-size:20px;font-style:inherit;line-height:1.4;margin:0px;padding:0px;\"><span style=\"font-size:20px;\"><span style=\"font-family:inherit;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\"><strong>Holidays in 2024</strong></span>&nbsp;</span></h3><p style=\"margin-left:0px;\">&nbsp;</p><p class=\"default__StyledText-sc-1jtxuc8-1 jQghZF body-paragraph\" style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">January 1: New Year\'s Day</span></p><p class=\"default__StyledText-sc-1jtxuc8-1 jQghZF body-paragraph\" style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Ramadan 29 to Shawwal 3, 1445 AH: Eid Al Fitr</span></p><p class=\"default__StyledText-sc-1jtxuc8-1 jQghZF body-paragraph\" style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Dhu Al-Hijjah 9, 1445 AH: Arafat Day</span></p><p class=\"default__StyledText-sc-1jtxuc8-1 jQghZF body-paragraph\" style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Dhu Al-Hijjah 10 to 12, 1445 AH: Eid Al Adha</span></p><p class=\"default__StyledText-sc-1jtxuc8-1 jQghZF body-paragraph\" style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Muharram 1, 1446 AH: Islamic New Year</span></p><p class=\"default__StyledText-sc-1jtxuc8-1 jQghZF body-paragraph\" style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">Rabi\' Al-Awwal 12, 1446 AH: Prophet Mohammed\'s birthday</span></p><p class=\"default__StyledText-sc-1jtxuc8-1 jQghZF body-paragraph\" style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:400;line-height:inherit;margin:0px 0px 20px;padding:0px;\"><span style=\"font-family:inherit;font-size:14px;font-style:inherit;font-weight:inherit;line-height:inherit;margin:0px;padding:0px;\">December 2 to 3: National Day</span></p></div>', 'published', 1, 'Botble\\ACL\\Models\\User', 0, 'products/cabinet-announces-public-holidays-in-the-uae-for-2024-1.webp', 0, NULL, '2024-12-24 06:16:38', '2024-12-24 06:17:15');
